class Solution {
    bool isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }
public:
    int maxVowels(string s, int k) {
        int count = 0;
        for (int i = 0; i < k; i++) {
            if (isVowel(s[i])) count++;
        }
        int best = count;
        int n = (int)s.size();
        for (int i = k; i < n; i++) {
            if (isVowel(s[i - k])) count--;
            if (isVowel(s[i])) count++;
            if (count > best) best = count;
        }
        return best;
    }
};
